    for identifier in diff['changed']:
        a,b=old[identifier],new[identifier];require(a.get('edge')==b.get('edge')=='1' and a.get('source')==b.get('source') and a.get('target')==b.get('target'),'changed_component_is_not_same_source_bound_edge');require(E.canonicalize(E.tostring(a.find('mxGeometry'),encoding='unicode'))==E.canonicalize(E.tostring(b.find('mxGeometry'),encoding='unicode')),'source_owned_edge_waypoint_geometry_changed');style=lambda cell:dict(part.split('=',1) for part in cell.get('style','').split(';') if '=' in part);x,y=style(a),style(b);fields=['strokeColor','strokeWidth','fillColor','gradientColor','opacity','strokeOpacity','fillOpacity','dashed','dashPattern','lineCap','lineJoin'];require(all(x.get(key)==y.get(key) for key in fields),'source_owned_edge_rgba_or_stroke_changed');styles.append({'edge':identifier,'rgba_and_stroke_properties':{key:x[key] for key in fields if key in x},'waypoint_geometry_exactly_unchanged':True,'source_and_target_identity_unchanged':True})
    return diff,{'fresh_source_marker_rule_replay':replay,'changed_edge_source_rgba_stroke_and_geometry':styles}

