def padded_edit_probe(browser,xml,markers,width,height,expected,work):
    pad=64;page=view(browser,xml,width,height,pad);baseline=shot(page);frame=array(baseline);crop=frame[pad:pad+height,pad:pad+width];crop_exact=np.array_equal(crop,array(expected));before_objects=page.evaluate(OBJECTS);reference_page=view(browser,xml,width,height)
